package mz.bam.seeky.android;
import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;
/** Shared course/module/material surfaces; titles are data, never translated. */
final class StudyUi {
 final MainActivity a;final AppPalette p;StudyUi(MainActivity a){this.a=a;p=AppPalette.of(a);}
 LinearLayout card(){LinearLayout c=a.card();GradientDrawable d=a.shape(p.surface,18);d.setStroke(a.dp(1),p.line);c.setBackground(d);return c;}
 TextView raw(String value,int sp,int color){TextView t=new TextView(a);t.setText(value);t.setTextSize(sp);t.setTextColor(color);t.setMaxLines(2);return t;}
 void unitHeading(LinearLayout card,String kind,String title,int number,Runnable menu){LinearLayout row=a.row();TextView index=raw(String.format(java.util.Locale.ROOT,"%02d",number),21,p.accent);index.setTypeface(null,Typeface.BOLD);index.setGravity(Gravity.CENTER);index.setBackground(a.shape(p.tint,12));row.addView(index,new LinearLayout.LayoutParams(a.dp(48),a.dp(56)));LinearLayout caption=a.column();caption.setPadding(a.dp(12),0,a.dp(8),0);caption.addView(a.label(kind,10,p.accent));TextView name=raw(title,17,p.ink);name.setTypeface(null,Typeface.BOLD);caption.addView(name);row.addView(caption,new LinearLayout.LayoutParams(0,-2,1));row.addView(a.iconButton("settings","Gerir módulo",menu),new LinearLayout.LayoutParams(a.dp(44),a.dp(48)));card.addView(row);}
 void heading(LinearLayout card,String symbol,String kind,String title,Runnable menu){LinearLayout row=a.row();FrameLayout tile=new FrameLayout(a);tile.setBackground(a.shape(p.tint,12));tile.addView(new Icons(a,symbol,p.accent),new FrameLayout.LayoutParams(a.dp(24),a.dp(24),Gravity.CENTER));row.addView(tile,new LinearLayout.LayoutParams(a.dp(44),a.dp(48)));LinearLayout text=a.column();text.setPadding(a.dp(12),0,a.dp(6),0);TextView over=a.label(kind,10,p.accent);over.setLetterSpacing(.08f);text.addView(over);TextView name=raw(title,18,p.ink);name.setTypeface(null,Typeface.BOLD);text.addView(name);row.addView(text,new LinearLayout.LayoutParams(0,-2,1));if(menu!=null)row.addView(a.iconButton("settings","Gerir",menu),new LinearLayout.LayoutParams(a.dp(44),a.dp(48)));card.addView(row);}
 void stats(LinearLayout card,String left,String right){a.gap(card,14);LinearLayout row=a.row();for(int n=0;n<2;n++){TextView t=raw(n==0?left:right,12,p.ink);t.setGravity(Gravity.CENTER);t.setPadding(a.dp(8),a.dp(10),a.dp(8),a.dp(10));t.setBackground(a.shape(p.tint,10));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);if(n==0)lp.rightMargin=a.dp(8);row.addView(t,lp);}card.addView(row);}
 void actions(LinearLayout card,String first,Runnable one,String second,Runnable two){a.gap(card,12);LinearLayout row=a.row();TextView primary=a.button(first,one);UiBox.style(primary);row.addView(primary,new LinearLayout.LayoutParams(0,-2,1));if(second!=null){TextView next=a.button(second,two);UiBox.style(next);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.leftMargin=a.dp(8);row.addView(next,lp);}card.addView(row);}
 void progress(LinearLayout card,int value){a.gap(card,12);ProgressBar bar=new ProgressBar(a,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);bar.setProgress(Math.max(0,Math.min(100,value)));bar.setProgressTintList(android.content.res.ColorStateList.valueOf(p.accent));bar.setProgressBackgroundTintList(android.content.res.ColorStateList.valueOf(p.line));card.addView(bar,new LinearLayout.LayoutParams(-1,a.dp(5)));}
}
